#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    int t;
    cin >> t;
    while(t--) {
        int n ;
        cin >> n;
        
        int sz = 3*n;
        vector<long long>a(sz);
        
        for(int i = 0 ; i < sz ; i++) {
            cin >> a[i];
        }
        
        sort(a.rbegin() , a.rend());
        
        vector<long long>pr(sz+1 ,0);
        
        for(int i = 0 ; i < sz ; i++) {
            pr[i + 1] = pr[i] + a[i];
        }
    
        long long ans = 0;
        for(int k = 0  ; k <= n ; k++) {
            int lo = 0;
            int hi = n - k;
            
            while(lo < hi) {
                int mi = (lo+ hi)/2;
                
                int p = k + 2*mi;
                int q = 3*n - 2*k- mi - 1;
                long long g = a[p] + a[p + 1] - 3LL*a[q];
                
                if(g >= 0 ) {
                    lo = mi + 1;
                }
                else hi = mi;
            }
            
            int l= lo;
            if(l >0) {
                int pre = l -1;
                int p = k+2*pre;
                int q =3*n-2*k-pre-1;
                
                if(a[p] + a[p +1] - 3LL*a[q] <0)l--;
            }
            
            int end = 3*n - 2*k - l;
            
            long long res = 2LL*pr[k] + pr[k + 2*l]+3LL*pr[end];
            
            ans = max(ans , res);
        }
        
        cout<<ans<<endl;
        
        
    }
}
